// GitHub arama sorgularını hazırlar (her sorgu ayrı bir öğe olur).
// Okuma zinciri hata verdiyse: dosya bozuk/erişilemez ise çalışma durdurulur —
// aksi hâlde "hiç görülmemiş" sanılıp tüm liste yeniden bildirilir.
const okuHata = $('Durumu Oku (GitHub)').first().json.error;
const okuMesaj = okuHata ? String(okuHata.message || okuHata) : '';
const dosyaYok = /ENOENT|no such file|not found/i.test(okuMesaj);
const cikarHata = $('Durumu Çıkar (GitHub)').first().json.error;
if (!dosyaYok && (okuHata || cikarHata)) {
  const m = okuMesaj || String((cikarHata && cikarHata.message) || cikarHata);
  throw new Error('github-durum.json okunamadı; veri kaybını önlemek için durduruldu → ' + m);
}

let elleCalisti = false;
try { elleCalisti = Boolean($('Elle Test Et (GitHub)').first()); } catch (e) { elleCalisti = false; }

const token = String($env.GITHUB_TOKEN || '').trim();
if (!token) {
  if (elleCalisti) {
    throw new Error('GITHUB_TOKEN boş. .env dosyasına bir GitHub token yazıp "docker compose up -d" ile yeniden başlatın.');
  }
  return []; // token yoksa workflow sessizce hiçbir şey yapmaz
}

const kim = String($env.GITHUB_KULLANICI || '').trim() || '@me';
const sorgular = [
  { anahtar: 'inceleme', ikon: '🔍', ad: 'İncelemeni bekleyen PR', q: 'is:open is:pr archived:false review-requested:' + kim },
  { anahtar: 'ci', ikon: '🔴', ad: "CI'ı kırık PR'ların", q: 'is:open is:pr archived:false author:' + kim + ' status:failure', taslakAtla: true },
  { anahtar: 'onay', ikon: '✅', ad: 'Onaylanmış, bekleyen PR', q: 'is:open is:pr archived:false author:' + kim + ' review:approved', taslakAtla: true },
  { anahtar: 'issue', ikon: '📌', ad: 'Sana atanmış issue', q: 'is:open is:issue archived:false assignee:' + kim },
  { anahtar: 'anma', ikon: '📣', ad: 'Adının geçtiği konular', q: 'is:open archived:false mentions:' + kim },
];

return sorgular.map((s) => ({
  json: {
    ...s,
    url: 'https://api.github.com/search/issues?per_page=20&sort=updated&order=desc&q=' + encodeURIComponent(s.q),
  },
}));

// Sorgu sonuçlarını önceki turla karşılaştırır: yalnızca YENİ kayıtlar bildirilir.
// Bir sorgu hata verdiyse o kategorinin eski işaretleri korunur; aksi hâlde
// sorun geçince tüm liste "yeni" sanılıp ikinci kez bildirilirdi.
const esc = (s) => String(s ?? '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const kisalt = (s, n = 70) => {
  const t = String(s || '').replace(/\s+/g, ' ').trim();
  return t.length > n ? t.slice(0, n) + '…' : t;
};
const repoAdi = (u) => String(u || '').split('/repos/')[1] || '';

const sorgular = $('Sorguları Hazırla').all().map((x) => x.json);
const sonuclar = $input.all();
const durumJson = $('Durumu Çıkar (GitHub)').first().json || {};
const durum = durumJson.data || durumJson || {};
const gorulenEski = Array.isArray(durum.gorulen) ? durum.gorulen : [];
const eskiOzet = (durum.ozet && typeof durum.ozet === 'object') ? durum.ozet : {};
const ilkCalisma = !durum.sonCalisma;

const yeniler = [];
const uyarilar = [];
const yeniUyarilar = [];
const ozet = {};
const guncel = [];
const korunan = [];

for (let i = 0; i < sorgular.length; i++) {
  const q = sorgular[i];
  const r = (sonuclar[i] && sonuclar[i].json) || {};
  const hamHata = r.error ? String(r.error.message || r.error) : '';
  const apiHata = !hamHata && !Array.isArray(r.items) ? String(r.message || 'beklenmeyen yanıt') : '';
  const hata = hamHata || apiHata;

  if (hata) {
    uyarilar.push(q.ad + ': ' + (
      /401|Bad credentials/i.test(hata) ? 'GITHUB_TOKEN geçersiz görünüyor'
      : /rate limit|403/i.test(hata) ? 'GitHub istek sınırı — sonraki turda tekrar denenecek'
      : /ENOTFOUND|EAI_AGAIN|ECONNREFUSED|timeout/i.test(hata) ? 'GitHub\'a ulaşılamadı'
      : kisalt(hata, 90)));
    korunan.push(...gorulenEski.filter((k) => k.indexOf(q.anahtar + '|') === 0));
    if (eskiOzet[q.anahtar]) ozet[q.anahtar] = eskiOzet[q.anahtar]; // eski görüntü korunur
    continue;
  }

  const kayitlar = (Array.isArray(r.items) ? r.items : []).map((it) => ({
    baslik: kisalt(it.title),
    repo: repoAdi(it.repository_url),
    no: it.number,
    url: it.html_url,
    kim: (it.user && it.user.login) || '',
    taslak: Boolean(it.draft),
    guncelleme: it.updated_at || null,
  }));
  ozet[q.anahtar] = { ad: q.ad, ikon: q.ikon, kayitlar };

  for (const k of kayitlar) {
    const anahtar = q.anahtar + '|' + k.url;
    guncel.push(anahtar);
    if (q.taslakAtla && k.taslak) continue;
    if (!gorulenEski.includes(anahtar)) yeniler.push({ ...k, kategori: q.ad, ikon: q.ikon });
  }
}

for (const u of uyarilar) {
  const anahtar = 'uyari|' + u;
  guncel.push(anahtar);
  if (!gorulenEski.includes(anahtar)) yeniUyarilar.push(u);
}

const gruplar = new Map();
for (const y of yeniler) {
  if (!gruplar.has(y.kategori)) gruplar.set(y.kategori, []);
  gruplar.get(y.kategori).push(y);
}

const satirlar = [];
const htmlBolum = [];
for (const [ad, kayitlar] of gruplar) {
  satirlar.push(kayitlar[0].ikon + ' ' + ad + ' (' + kayitlar.length + ')');
  htmlBolum.push('<h3 style="margin:14px 0 4px">' + kayitlar[0].ikon + ' ' + esc(ad) + '</h3><ul>');
  for (const k of kayitlar.slice(0, 6)) {
    satirlar.push('• ' + k.repo + '#' + k.no + ' — ' + k.baslik + '\n  ' + k.url);
    htmlBolum.push('<li style="margin:4px 0"><a href="' + esc(k.url) + '">' + esc(k.repo) + '#' + k.no +
      '</a> — ' + esc(k.baslik) + '</li>');
  }
  if (kayitlar.length > 6) {
    satirlar.push('  …ve ' + (kayitlar.length - 6) + ' tane daha');
    htmlBolum.push('<li style="color:#999">…ve ' + (kayitlar.length - 6) + ' tane daha</li>');
  }
  htmlBolum.push('</ul>');
  satirlar.push('');
}
for (const u of yeniUyarilar) {
  satirlar.push('⚠️ ' + u);
  htmlBolum.push('<p style="color:#b45309">⚠️ ' + esc(u) + '</p>');
}

const gonderilecek = !ilkCalisma && (yeniler.length > 0 || yeniUyarilar.length > 0);
const text = satirlar.join('\n').trim();
const html = '<div style="font-family:sans-serif;max-width:640px"><h2>🐙 GitHub</h2>' + htmlBolum.join('') + '</div>';
const konu = '[n8n] 🐙 GitHub: ' + (yeniler.length
  ? yeniler.length + ' yeni kayıt'
  : yeniUyarilar.length + ' uyarı');

return [{
  json: {
    gorulen: [...new Set([...guncel, ...korunan])].slice(-500),
    ozet,
    sonCalisma: new Date().toISOString(),
    gonderilecek,
    yazilsin: true,
    ilkCalisma,
    yeniSayisi: yeniler.length,
    text,
    html,
    konu,
  },
}];

// Telegram kuruluysa bildirim oraya gider; değilse bu dal boş döner.
const token = String($env.TELEGRAM_BOT_TOKEN || '').trim();
const chat = String($env.TELEGRAM_CHAT_ID || '').trim();
if (!token || !chat) return [];
return [{ json: { chat_id: chat, text: ('🐙 GitHub\n\n' + $input.first().json.text).slice(0, 3900) } }];

// Telegram kurulu DEĞİLSE bildirim mail olarak gider (çift mesaj olmasın).
const kurulu = String($env.TELEGRAM_BOT_TOKEN || '').trim() && String($env.TELEGRAM_CHAT_ID || '').trim();
if (kurulu) return [];
const j = $input.first().json;
return [{ json: { konu: j.konu, html: j.html } }];

// Dosyaya yalnızca durum kaydı yazılır (görülen anahtarlar + son görüntü).
const j = $input.first().json;
if (!j.yazilsin) return [];
return [{ json: { gorulen: j.gorulen, ozet: j.ozet, sonCalisma: j.sonCalisma } }];

// Telegram'dan /pr komutu gelince son taramanın tamamını özetler.
// Yeni istek atmaz — zamanlanmış turun (en fazla 15 dk önce) yazdığını okur.
const cagri = $('Workflow 05\'ten Çağrı (GitHub)').first().json || {};
const chat = cagri.chat_id ? String(cagri.chat_id) : '';
if (!chat) return [];

const okuHata = $('Durumu Oku (Rapor)').first().json.error;
const okuMesaj = okuHata ? String(okuHata.message || okuHata) : '';
const cikarHata = $('Durumu Çıkar (Rapor)').first().json.error;
if (okuHata || cikarHata) {
  const dosyaYok = /ENOENT|no such file|not found/i.test(okuMesaj);
  return [{ json: { chat_id: chat, text: dosyaYok
    ? '🐙 Henüz tarama yapılmadı. Workflow 17/18 Active mi? Kurulum: cp local-files/github-durum.ornek.json local-files/github-durum.json'
    : '🐙 github-durum.json okunamadı: ' + (okuMesaj || 'bozuk dosya') } }];
}

const j = $input.first().json || {};
const durum = j.data || j || {};
const ozet = (durum.ozet && typeof durum.ozet === 'object') ? durum.ozet : {};
const sira = ['inceleme', 'ci', 'onay', 'issue', 'anma'];

const gecen = (iso) => {
  if (!iso) return 'henüz tarama yapılmadı';
  const dk = Math.round((Date.now() - new Date(iso).getTime()) / 60000);
  if (!Number.isFinite(dk)) return 'bilinmiyor';
  if (dk < 1) return 'az önce';
  if (dk < 60) return dk + ' dk önce';
  const sa = Math.floor(dk / 60);
  return sa < 24 ? sa + ' sa önce' : Math.floor(sa / 24) + ' gün önce';
};

const bolumler = [];
let toplam = 0;
for (const anahtar of sira) {
  const b = ozet[anahtar];
  if (!b || !Array.isArray(b.kayitlar) || b.kayitlar.length === 0) continue;
  toplam += b.kayitlar.length;
  bolumler.push(b.ikon + ' ' + b.ad + ' (' + b.kayitlar.length + ')');
  for (const k of b.kayitlar.slice(0, 5)) {
    bolumler.push('• ' + k.repo + '#' + k.no + ' — ' + k.baslik + (k.taslak ? ' (taslak)' : '') + '\n  ' + k.url);
  }
  if (b.kayitlar.length > 5) bolumler.push('  …ve ' + (b.kayitlar.length - 5) + ' tane daha');
  bolumler.push('');
}

const text = (toplam === 0
  ? '🐙 GitHub: sizi bekleyen bir şey yok. 🎉'
  : '🐙 GitHub\n\n' + bolumler.join('\n').trim()) + '\n\nSon tarama: ' + gecen(durum.sonCalisma);

return [{ json: { chat_id: chat, text: text.slice(0, 3900) } }];
